CREATE TABLE orders_MenuItems (  menuItemID INTEGER PRIMARY KEY AUTOINCREMENT,  itemName TEXT NOT NULL,  price REAL NOT NULL);
CREATE TABLE orders_OrderItems (  orderItemID INTEGER PRIMARY KEY AUTOINCREMENT,  orderID INTEGER NOT NULL,  menuItemID INTEGER NOT NULL,  itemName TEXT NOT NULL,  quantity INTEGER NOT NULL DEFAULT 1,  priceAtOrder REAL NOT NULL DEFAULT 0,  FOREIGN KEY (orderID) REFERENCES orders_Orders(orderID),  FOREIGN KEY (menuItemID) REFERENCES orders_MenuItems(menuItemID));
CREATE TABLE orders_Orders (  orderID INTEGER PRIMARY KEY AUTOINCREMENT,  customerName TEXT NOT NULL DEFAULT 'Guest',  orderDate DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,  status TEXT NOT NULL DEFAULT 'Pending',  totalAmount REAL NOT NULL DEFAULT 0);
CREATE TABLE product_Category (
    categoryID INTEGER PRIMARY KEY AUTOINCREMENT,
    chosenSortBy TEXT NOT NULL DEFAULT '',
    chosenDietary TEXT NOT NULL,
    chosenHealthGoal TEXT NOT NULL,
    chosenCuisines TEXT NOT NULL,
    productID INTEGER NOT NULL UNIQUE,
    FOREIGN KEY (productID) REFERENCES product_Products(productID) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE TABLE product_Chef (
    chefID INTEGER PRIMARY KEY AUTOINCREMENT,
    chefName TEXT NOT NULL UNIQUE,
    "chefRating&ReviewID" INTEGER NOT NULL DEFAULT 0,
    chefDescription TEXT NOT NULL,
    chefTag1 TEXT NOT NULL DEFAULT '',
    chefTag2 TEXT NOT NULL DEFAULT '',
    chefTag3 TEXT NOT NULL DEFAULT '',
    chefImage TEXT NOT NULL DEFAULT '',
    chefEmail TEXT NOT NULL DEFAULT '',
    chefTel TEXT NOT NULL DEFAULT ''
);
CREATE TABLE product_ChefReview (
    reviewID INTEGER PRIMARY KEY AUTOINCREMENT,
    chefID INTEGER NOT NULL,
    reviewerName TEXT NOT NULL DEFAULT '',
    rating REAL NOT NULL DEFAULT 0 CHECK(rating BETWEEN 0 AND 5),
    reviewText TEXT NOT NULL DEFAULT '',
    reviewDate DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (chefID) REFERENCES product_Chef(chefID) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE TABLE product_DefaultIngredient (
    defaultIngredientID INTEGER PRIMARY KEY AUTOINCREMENT,
    defaultIngredients TEXT NOT NULL,
    totalCalories REAL NOT NULL DEFAULT 0,
    totalProtein REAL NOT NULL DEFAULT 0,
    totalCarbohydrates REAL NOT NULL DEFAULT 0,
    totalSugars REAL NOT NULL DEFAULT 0,
    totalFat REAL NOT NULL DEFAULT 0,
    totalSaturatedFat REAL NOT NULL DEFAULT 0,
    totalFiber REAL NOT NULL DEFAULT 0,
    totalSodium REAL NOT NULL DEFAULT 0,
    productID INTEGER NOT NULL,
    FOREIGN KEY (productID) REFERENCES product_Products(productID) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE TABLE product_Ingredient (
    ingredientID INTEGER PRIMARY KEY AUTOINCREMENT,
    ingredientName TEXT NOT NULL UNIQUE,
    calories REAL NOT NULL DEFAULT 0 CHECK(calories >= 0),
    protein REAL NOT NULL DEFAULT 0 CHECK(protein >= 0),
    carbohydrates REAL NOT NULL DEFAULT 0 CHECK(carbohydrates >= 0),
    sugars REAL NOT NULL DEFAULT 0 CHECK(sugars >= 0),
    fat REAL NOT NULL DEFAULT 0 CHECK(fat >= 0),
    saturatedFat REAL NOT NULL DEFAULT 0 CHECK(saturatedFat >= 0),
    fiber REAL NOT NULL DEFAULT 0 CHECK(fiber >= 0),
    sodium REAL NOT NULL DEFAULT 0 CHECK(sodium >= 0)
);
CREATE TABLE product_ProductImage (
    imageID INTEGER PRIMARY KEY AUTOINCREMENT,
    imageURL TEXT NOT NULL,
    altText TEXT NOT NULL DEFAULT '',
    displayOrder INTEGER NOT NULL CHECK(displayOrder > 0),
    uploadDate DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    productID INTEGER NOT NULL,
    FOREIGN KEY (productID) REFERENCES product_Products(productID) ON UPDATE CASCADE ON DELETE CASCADE,
    UNIQUE(productID, displayOrder)
);
CREATE TABLE product_ProductIngredientOption (
    optionID INTEGER PRIMARY KEY AUTOINCREMENT,
    productID INTEGER NOT NULL,
    ingredientID INTEGER,
    optionGroup TEXT NOT NULL CHECK(optionGroup IN ('Base', 'Protein', 'Add-On')),
    optionName TEXT NOT NULL,
    extraPrice REAL NOT NULL DEFAULT 0 CHECK(extraPrice >= 0),
    selectedByDefault INTEGER NOT NULL DEFAULT 0 CHECK(selectedByDefault IN (0, 1)),
    allowMultiple INTEGER NOT NULL DEFAULT 1 CHECK(allowMultiple IN (0, 1)),
    status INTEGER NOT NULL DEFAULT 1 CHECK(status IN (0, 1)),
    FOREIGN KEY (productID) REFERENCES product_Products(productID) ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY (ingredientID) REFERENCES product_Ingredient(ingredientID) ON UPDATE CASCADE ON DELETE SET NULL,
    UNIQUE(productID, optionGroup, optionName)
);
CREATE TABLE product_Products (
    productID INTEGER PRIMARY KEY AUTOINCREMENT,
    productName TEXT NOT NULL UNIQUE,
    shortDescription TEXT NOT NULL,
    extendedDescription TEXT NOT NULL,
    cost REAL NOT NULL CHECK(cost >= 0),
    price REAL NOT NULL CHECK(price >= 0),
    status INTEGER NOT NULL DEFAULT 1 CHECK(status IN (0, 1)),
    spiceLevel INTEGER NOT NULL DEFAULT 0 CHECK(spiceLevel BETWEEN 0 AND 5),
    country TEXT NOT NULL,
    createdDate DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updatedDate DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    chefID INTEGER NOT NULL,
    FOREIGN KEY (chefID) REFERENCES product_Chef(chefID) ON UPDATE CASCADE ON DELETE RESTRICT
);
What makes it stand out is the use of fermented kimchi, which not only enhances flavour but also supports gut health by introducing beneficial probiotics. It’s a quick, satisfying meal that feels indulgent while still offering nutritional value, especially when paired with vegetables or plant-based proteins.',5.0,9.99,1,5,'South Korea','2026-04-09 00:00:00','2026-04-09 00:00:00',2);
CREATE TABLE product_Ratings (
    rateID INTEGER PRIMARY KEY AUTOINCREMENT,
    rating REAL NOT NULL DEFAULT 0 CHECK(rating BETWEEN 0 AND 5),
    noPeople INTEGER NOT NULL DEFAULT 0 CHECK(noPeople >= 0),
    productID INTEGER NOT NULL UNIQUE,
    FOREIGN KEY (productID) REFERENCES product_Products(productID) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE TABLE reviews_admin_moderation_log(id INTEGER PRIMARY KEY AUTOINCREMENT,admin_id INTEGER NOT NULL REFERENCES reviews_users(id),review_id INTEGER NOT NULL REFERENCES reviews_reviews(id),action TEXT NOT NULL,created_at INTEGER NOT NULL,notes TEXT);
CREATE TABLE reviews_helpful_votes(id INTEGER PRIMARY KEY AUTOINCREMENT,review_id INTEGER NOT NULL REFERENCES reviews_reviews(id),customer_id INTEGER NOT NULL REFERENCES reviews_users(id),vote_type TEXT NOT NULL CHECK(vote_type IN ('helpful','unhelpful')),created_at INTEGER NOT NULL,UNIQUE(review_id,customer_id));
CREATE TABLE reviews_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,customer_id INTEGER NOT NULL REFERENCES reviews_users(id),product_id INTEGER NOT NULL REFERENCES reviews_products(id),order_date TEXT NOT NULL);
CREATE TABLE reviews_products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,price REAL NOT NULL CHECK(price>0),stock INTEGER NOT NULL CHECK(stock>=0),category TEXT,average_rating REAL NOT NULL DEFAULT 0);
CREATE TABLE reviews_reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL REFERENCES reviews_products(id),customer_id INTEGER NOT NULL REFERENCES reviews_users(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment_text TEXT NOT NULL,image_url TEXT,created_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'Active',helpful_count INTEGER NOT NULL DEFAULT 0,unhelpful_count INTEGER NOT NULL DEFAULT 0,edit_duration_seconds INTEGER NOT NULL DEFAULT 300,UNIQUE(product_id,customer_id));
CREATE TABLE reviews_users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('CUSTOMER','ADMIN')),address TEXT);
CREATE INDEX "product_idx_category_product" ON product_Category(productID);
CREATE INDEX "product_idx_chefreview_chef" ON product_ChefReview(chefID);
CREATE INDEX "product_idx_defaultingredient_product" ON product_DefaultIngredient(productID);
CREATE INDEX "product_idx_options_product" ON product_ProductIngredientOption(productID);
CREATE INDEX "product_idx_productimage_product" ON product_ProductImage(productID);
CREATE INDEX "product_idx_products_chef" ON product_Products(chefID);
CREATE INDEX "product_idx_ratings_product" ON product_Ratings(productID);
DELETE FROM "sqlite_sequence";
COMMIT;
